(()=>{const key='rei-toolkit-progress';const ids=['proposal','matrix','search','framework','methods','checklist'];function read(){try{return JSON.parse(localStorage.getItem(key)||'[]').filter(x=>ids.includes(x))}catch{return[]}}function mount(){if(location.hash!=='#toolkit'||document.querySelector('#toolkit-progress'))return;const done=read(),body=document.querySelector('.resource-grid');if(!body)return;const bar=document.createElement('div');bar.id='toolkit-progress';bar.className='toolkit-progress';bar.innerHTML='<strong>'+done.length+' of '+ids.length+' resources completed</strong><span>Mark a resource after you adapt or use it.</span>';body.before(bar);document.querySelectorAll('[data-download]').forEach(b=>{const id=b.dataset.download;if(!ids.includes(id))return;const x=document.createElement('button');x.className='text-button';x.dataset.toolkitComplete=id;x.textContent=done.includes(id)?'Completed ✓':'Mark complete';b.parentElement.append(x)})}document.addEventListener('click',e=>{const b=e.target.closest('[data-toolkit-complete]');if(!b)return;const done=read(),id=b.dataset.toolkitComplete,next=done.includes(id)?done.filter(x=>x!==id):done.concat(id);localStorage.setItem(key,JSON.stringify(next));b.textContent=next.includes(id)?'Completed ✓':'Mark complete';const bar=document.querySelector('#toolkit-progress strong');if(bar)bar.textContent=next.length+' of '+ids.length+' resources completed'});addEventListener('rrh:route',mount);mount()})()